import{_ as e,c as t,o as s,a2 as a}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Stylesheets","description":"","frontmatter":{"sidebarPos":4,"sidebarTitle":"Stylesheets","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/stylesheets.md","filePath":"guide/cms/stylesheets.md","lastUpdated":1784841066000}'),i={name:"guide/cms/stylesheets.md"},d=a(`<h1 id="stylesheets" tabindex="-1">Stylesheets <a class="header-anchor" href="#stylesheets" aria-label="Permalink to &quot;Stylesheets&quot;">​</a></h1><p>A <strong>StyleSheet</strong> is a compiled CSS bundle (optional SCSS / raw CSS / utilities) plus framework metadata. <a href="./layout-builders">Layout builders</a> attach sheets; public pages receive <code>&lt;link&gt;</code> tags via <code>StylesheetManager</code>.</p><p>Unlike LayoutBuilder / PageLayout, stylesheets are <strong>not</strong> Blade <code>blade_source</code> trees — output is CSS on a filesystem disk + an optional public HTTP route.</p><h2 id="ordering" tabindex="-1">Ordering <a class="header-anchor" href="#ordering" aria-label="Permalink to &quot;Ordering&quot;">​</a></h2><p>For one sheet (<code>linkHrefsForSheet</code>):</p><ol><li>Framework link hrefs (from sheet <code>definition</code> + config maps: Bootstrap / Tailwind)</li><li>Public compiled bundle URL (<code>cms.public.stylesheet</code>) when the sheet is <strong>published</strong> and the public route is enabled</li></ol><p>For a LayoutBuilder: primary <code>style_sheet_id</code>, then each <code>style_sheet_slugs</code> entry (published only; missing/unpublished skipped; duplicate ids/hrefs deduped).</p><h2 id="where-compiled-css-lives" tabindex="-1">Where compiled CSS lives <a class="header-anchor" href="#where-compiled-css-lives" aria-label="Permalink to &quot;Where compiled CSS lives&quot;">​</a></h2><table><thead><tr><th>Config</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>cms_stylesheets.compiled_disk</code></td><td><code>local</code></td><td>Laravel filesystem disk</td></tr><tr><td><code>cms_stylesheets.compiled_directory</code></td><td><code>modularous/cms/stylesheets</code></td><td>Directory on that disk (no leading/trailing slash)</td></tr></tbody></table><p>Typical local path: <code>storage/app/modularous/cms/stylesheets/…</code> (depends on the <code>local</code> disk root).</p><p>Persisted via <code>StyleSheetRepository</code>. Optional SCSS: <code>cms_stylesheets.scssphp.enabled</code> (default <strong>false</strong>; needs <code>scssphp/scssphp</code>).</p><p>Other caps:</p><table><thead><tr><th>Key</th><th>Default</th></tr></thead><tbody><tr><td><code>max_raw_css_bytes</code></td><td><code>512000</code></td></tr><tr><td><code>max_inline_vendor_css_bytes</code></td><td><code>2000000</code></td></tr><tr><td><code>utilities_class_prefix</code></td><td><code>u-</code></td></tr><tr><td><code>allow_http_fetch_for_inline_merge</code></td><td><code>false</code></td></tr></tbody></table><h2 id="public-css-route" tabindex="-1">Public CSS route <a class="header-anchor" href="#public-css-route" aria-label="Permalink to &quot;Public CSS route&quot;">​</a></h2><p>Registered in <code>CmsPublicSystemRoutes</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /{path_prefix}/{slug}.css</span></span></code></pre></div><table><thead><tr><th>Config</th><th>Default</th></tr></thead><tbody><tr><td><code>public_route.enabled</code></td><td><code>true</code></td></tr><tr><td><code>public_route.path_prefix</code></td><td><code>cms/stylesheets</code></td></tr><tr><td><code>public_route.max_age_seconds</code></td><td><code>3600</code></td></tr><tr><td><code>public_route.cache_bust_query</code></td><td><code>true</code></td></tr><tr><td><code>public_route.cache_bust_param</code></td><td><code>v</code></td></tr></tbody></table><p>Bound to the public front domain; catch-all excludes this prefix automatically (<a href="./public-routing">Public routing</a>).</p><p>Manual rebuild: <code>POST api/cms/style-sheets/{id}/recompile</code> when your API middleware allows it.</p><h2 id="framework-href-maps" tabindex="-1">Framework href maps <a class="header-anchor" href="#framework-href-maps" aria-label="Permalink to &quot;Framework href maps&quot;">​</a></h2><p>Config nests <code>bootstrap.*</code> and <code>tailwind.*</code> map versions → vendor/CDN/build CSS (and Bootstrap JS bundle) paths. Demo assets ship under <code>public/vendor/cms-stylesheet-examples/…</code> and <code>public/build/cms-stylesheet-examples/…</code>. Prefer local <code>/</code> paths; HTTP fetch for inlining is off by default.</p><h2 id="blade-snippet" tabindex="-1">Blade snippet <a class="header-anchor" href="#blade-snippet" aria-label="Permalink to &quot;Blade snippet&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Modules\\Cms\\Support\\StylesheetManager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">linkHrefsForLayoutBuilder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($layoutBuilder) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $href)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> rel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> href</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$href</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> }}&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@endforeach</span></span></code></pre></div><h2 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h2><p>Full table: <a href="./configuration">Configuration</a> → <code>modularous.cms_stylesheets</code>.</p><p><strong>Next:</strong> <a href="./layout-builders">Layout builders</a> (attach sheets to a document shell).</p>`,26),o=[d];function l(r,c,h,n,p,u){return s(),t("div",null,o)}const y=e(i,[["render",l]]);export{b as __pageData,y as default};
